const tests = [
 {id:1,title:'N5 模擬試験（もぎしけん）',vocab:21,grammar:22,listening:24},
 {id:2,title:'N5 模擬試験（もぎしけん）',vocab:20,grammar:23,listening:24},
 {id:3,title:'N5 模擬試験（もぎしけん）',vocab:22,grammar:21,listening:25},
];
const questions = {
 vocab:[
  {jp:'毎朝（まいあさ）、六時（ろくじ）に＿＿。',en:'Every morning, I ___ at six o’clock.',opts:['おきます','ねます','たべます','のみます'],answer:0},
  {jp:'この本（ほん）は＿＿ですか。',en:'How much is this book?',opts:['いくら','どこ','だれ','いつ'],answer:0}
 ],
 grammar:[
  {jp:'私（わたし）は日本語（にほんご）＿＿勉強（べんきょう）します。',en:'I study Japanese.',opts:['を','に','で','が'],answer:0},
  {jp:'昨日（きのう）、学校（がっこう）＿＿行（い）きませんでした。',en:'Yesterday, I did not go to school.',opts:['へ','を','が','も'],answer:0}
 ],
 listening:[
  {jp:'音声（おんせい）を聞（き）いて、正（ただ）しい答（こた）えを選（えら）んでください。',en:'Listen and choose the correct answer.',opts:['七時（しちじ）','八時（はちじ）','九時（くじ）','十時（じゅうじ）'],answer:1}
 ]
};
let currentQuestion=null, translationShown=false;
const app=document.querySelector('#app');

function nav(){return `<header class="topbar"><div class="shell nav"><button class="brand nav-btn" onclick="go('home')"><span class="mark">日</span><span>japanesenx</span></button><nav class="links"><button class="nav-btn" onclick="scrollToId('practice')">Practice</button><button class="nav-btn" onclick="scrollToId('tests')">Test</button><button class="nav-btn" onclick="scrollToId('about')">About us</button><button class="login-btn" onclick="openLogin()">Login</button></nav><button class="mobile-menu" onclick="openMenu()" aria-label="Open menu">☰</button></div></header>`}
function testCards(){return tests.map(t=>`<article class="test-card"><div class="test-top"><div><span class="setno">SET ${String(t.id).padStart(2,'0')}</span><h3>${t.title}</h3></div><span class="pill">90 min</span></div><div class="score-row"><span>Vocabulary · 語彙（ごい）</span><b>— / ${t.vocab}</b></div><div class="score-row"><span>Grammar & Reading</span><b>— / ${t.grammar}</b></div><div class="score-row"><span>Listening · 聴解（ちょうかい）</span><b>— / ${t.listening}</b></div><button class="details-btn" onclick="openTest(${t.id})">View paper →</button></article>`).join('')}
function home(){app.innerHTML=`${nav()}<main><section class="shell hero"><div><div class="eyebrow">JLPT N5 · 日本語能力試験</div><h1>Small steps.<br><span>Big fluency.</span></h1><p class="lead">Focused Japanese practice and true-to-format mock exams, built to make N5 preparation feel clear, calm, and achievable.</p><div class="actions"><button class="primary" onclick="scrollToId('practice')">Start practicing</button><button class="secondary" onclick="scrollToId('tests')">Explore mock tests</button></div></div><div class="hero-art"><div class="sun"></div><div class="paper"><div class="paper-lines"><i></i><i></i></div><div class="paper-kanji">学</div><div class="paper-lines"><i></i><i></i><i></i></div><div class="stamp">合格</div></div><div class="scribble">毎日すこしずつ</div></div></section><div class="shell stats"><div class="stat"><strong>3 practice modes</strong><span>Train one skill at a time</span></div><div class="stat"><strong>90 minutes</strong><span>Full N5 exam simulation</span></div><div class="stat"><strong>ふりがな</strong><span>Read every kanji with confidence</span></div></div>
<section class="shell section" id="practice"><div class="section-head"><div><div class="eyebrow">Daily training · 練習（れんしゅう）</div><h2>Practice your weak spots.</h2><p>Jump into a random question from any available N5 paper.</p></div><div class="level-switch"><button class="active">N5</button><button disabled>N4</button><button disabled>N3</button><button disabled>N2</button><button disabled>N1</button></div></div><div class="practice-grid"><article class="practice-card" data-jp="語"><div class="iconbox">あ</div><h3>Vocabulary</h3><div class="jp-label">語彙（ごい）</div><p>Build confidence with words, kanji readings, and meaning in context.</p><button class="text-link" onclick="openPractice('vocab')">Practice randomly →</button></article><article class="practice-card" data-jp="文"><div class="iconbox">文</div><h3>Grammar & Reading</h3><div class="jp-label">文法（ぶんぽう）・読解（どっかい）</div><p>Master particles, sentence patterns, and short reading passages.</p><button class="text-link" onclick="openPractice('grammar')">Practice randomly →</button></article><article class="practice-card" data-jp="聴"><div class="iconbox">♫</div><h3>Listening</h3><div class="jp-label">聴解（ちょうかい）</div><p>Train your ear for everyday conversations and key information.</p><button class="text-link" onclick="openPractice('listening')">Practice randomly →</button></article></div></section>
<section class="tests-bg" id="tests"><div class="shell"><div class="section-head"><div><div class="eyebrow" style="color:#f2c75c">Timed papers · 模擬試験（もぎしけん）</div><h2>N5 mock tests</h2><p>Take one section or complete the whole paper in 90 minutes.</p></div><div class="level-switch"><button class="active">N5</button><button disabled>N4</button><button disabled>N3</button><button disabled>N2</button><button disabled>N1</button></div></div><div class="test-grid">${testCards()}</div><div class="random-banner"><div><b>Not sure where to begin? おまかせ</b><p>Get a surprise question from any N5 set and section.</p></div><button class="secondary" onclick="openPractice('random')">Shuffle a question ↻</button></div></div></section>
<section class="shell section" id="about" style="padding-top:100px"><div class="about"><div><div class="eyebrow">Our approach</div><h2>Less guessing.<br>More growing.</h2></div><div class="about-copy"><p>Japanesenx is a focused home for JLPT preparation. We pair exam-like papers with low-pressure daily practice, so learners can understand mistakes and build durable confidence.</p><div class="principles"><div class="principle"><b>Kanji, made readable</b><small>Every kanji includes its hiragana reading.</small></div><div class="principle"><b>Progress that stays</b><small>Sign in to keep your personal best scores.</small></div></div></div></div></section></main><footer><div class="shell footer-in"><span>© 2026 Japanesenx</span><span>Made for 日本語（にほんご） learners</span></div></footer>`}
function modal(body){document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="modal" onclick="if(event.target===this)closeModal()"><div class="modal">${body}</div></div>`)}
function closeModal(){document.querySelector('#modal')?.remove()}
function openPractice(type){const pool=type==='random'?Object.values(questions).flat():questions[type];currentQuestion=pool[Math.floor(Math.random()*pool.length)];translationShown=false;renderQuestion(type)}
function renderQuestion(type){closeModal();modal(`<div class="modal-head"><div><div class="eyebrow">N5 quick practice</div><h2>${type==='random'?'Random mix':type==='vocab'?'Vocabulary':type==='grammar'?'Grammar & Reading':'Listening'}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="question-meta">Question from all active sets</div>${type==='listening'?'<button class="secondary" style="margin-top:14px" onclick="speakQuestion()">▶ Play audio</button>':''}<div class="question">${currentQuestion.jp}</div><div class="translation ${translationShown?'':'hidden'}" id="translation">${currentQuestion.en}</div><button class="secondary" style="padding:9px 13px;margin-bottom:16px" onclick="revealTranslation()">${translationShown?'Hide':'Reveal'} in English</button><div class="options">${currentQuestion.opts.map((o,i)=>`<button class="option" onclick="answer(${i})"><b>${i+1}.</b> ${o}</button>`).join('')}</div><div class="row-actions"><button class="secondary" onclick="openPractice('${type}')">Skip / Next question</button></div>`)}
function revealTranslation(){translationShown=!translationShown;document.querySelector('#translation').classList.toggle('hidden',!translationShown);event.currentTarget.textContent=`${translationShown?'Hide':'Reveal'} in English`}
function answer(i){const right=i===currentQuestion.answer;toast(right?'正解（せいかい）！ Correct 🎉':'もう一度（いちど）。 Try again.');if(right)setTimeout(()=>openPractice('random'),700)}
function speakQuestion(){if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(currentQuestion.jp.replace(/（.*?）/g,''));u.lang='ja-JP';speechSynthesis.speak(u)}}
function openTest(id){const t=tests.find(x=>x.id===id);modal(`<div class="modal-head"><div><div class="eyebrow">Set ${String(id).padStart(2,'0')}</div><h2>${t.title}</h2></div><button class="close" onclick="closeModal()">×</button></div><p style="color:var(--muted);line-height:1.7">Choose one section for focused testing, or sit the complete 90-minute paper. Your highest score is saved when you’re logged in.</p><div class="options"><button class="option" onclick="startTest('vocab',${id})"><b>Vocabulary · 語彙（ごい）</b><br><small>${t.vocab} questions · 20 minutes</small></button><button class="option" onclick="startTest('grammar',${id})"><b>Grammar & Reading</b><br><small>${t.grammar} questions · 40 minutes</small></button><button class="option" onclick="startTest('listening',${id})"><b>Listening · 聴解（ちょうかい）</b><br><small>${t.listening} questions · 30 minutes</small></button></div><button class="primary" style="width:100%" onclick="startTest('all',${id})">Start full 90-minute test →</button>`)}
function startTest(type,id){closeModal();toast(`${type==='all'?'90-minute full paper':type} · Set ${id} started`);setTimeout(()=>openPractice(type==='all'?'random':type),700)}
function openLogin(){modal(`<div class="modal-head"><div><div class="eyebrow">Welcome back</div><h2>Save your progress</h2></div><button class="close" onclick="closeModal()">×</button></div><form class="login-form" onsubmit="fakeLogin(event)"><label>Email<input type="email" required placeholder="you@example.com"></label><label>Password<input type="password" required minlength="6" placeholder="At least 6 characters"></label><div class="notice">Demo sign-in: this prototype stores your session safely in this browser only.</div><button class="primary" type="submit">Login</button></form>`)}
function fakeLogin(e){e.preventDefault();localStorage.setItem('jnx-user','Learner');closeModal();toast('おかえりなさい！ Welcome back.')}
function openMenu(){modal(`<div class="modal-head"><b>Menu · メニュー</b><button class="close" onclick="closeModal()">×</button></div><div class="options"><button class="option" onclick="closeModal();scrollToId('practice')">Practice</button><button class="option" onclick="closeModal();scrollToId('tests')">Test</button><button class="option" onclick="closeModal();scrollToId('about')">About us</button><button class="option" onclick="closeModal();openLogin()">Login</button></div>`)}
function scrollToId(id){document.querySelector('#'+id)?.scrollIntoView({behavior:'smooth'})}function go(){window.scrollTo({top:0,behavior:'smooth'})}function toast(msg){document.querySelector('.toast')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="toast">${msg}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),2300)}
home();
